def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_pressure = 0.0
    weak_pressure = 0.0
    rich_alive = 0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            if opp.get('budget', 0) >= 100:
                rich_alive += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > strong_pressure:
                    strong_pressure = float(bid)
                if opp.get('budget', 0) < 120 and float(bid) > weak_pressure:
                    weak_pressure = float(bid)

    if not alive:
        return max(0.0, min(budget, 15.0))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    danger = 0.0
    if hp <= 0:
        danger += 1.0
    elif hp <= 2:
        danger += 0.75
    elif hp <= 4:
        danger += 0.45
    elif hp <= 7:
        danger += 0.2
    danger += min(0.5, no_water_days * 0.22)

    base = DAILY_SALARY * (0.22 + 0.28 * scarcity + 0.55 * danger)

    if prev_bids:
        if strong_pressure >= 110:
            if danger < 0.7 and supply >= 20:
                base = min(base, DAILY_SALARY * 0.22)
            else:
                base = max(base, min(strong_pressure * 0.72, DAILY_SALARY * 1.05))
        elif strong_pressure >= 70:
            base = max(base, min(strong_pressure + 2.0, DAILY_SALARY * 1.0))
        else:
            target = weak_pressure + 2.0 if weak_pressure > 0 else DAILY_SALARY * 0.45
            base = max(base, target)

    if supply >= 22 and danger < 0.7:
        base *= 0.72
    elif supply <= 17:
        base *= 1.18

    if rich_alive >= 1 and danger < 0.75:
        base *= 0.9

    if day >= 8:
        base *= 1.12
    if day == 10:
        base *= 1.2

    reserve = 0.0
    days_left = max(0, 10 - day)
    if days_left >= 2 and hp > 3:
        reserve = days_left * 8.0

    affordable = max(0.0, budget - reserve)
    bid = min(base, budget)
    if affordable > 0:
        bid = min(bid, max(affordable, min(budget, 12.0 + 6.0 * danger)))

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, max(75.0, strong_pressure + 3.0 if strong_pressure > 0 else 75.0)))

    if budget < 25:
        bid = min(bid, budget)
    else:
        bid = min(budget, max(0.0, bid))

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    max_prev = max(yesterday_bids) if yesterday_bids else 80.0

    if my_status['hp'] < 4:
        return float(min(my_status['budget'], DAILY_SALARY * 0.9))

    if supply < WATER_REQ * 1.5:
        return float(min(my_status['budget'], max_prev + 5.0))

    return float(min(my_status['budget'], max(50.0, max_prev * 0.8)))
